def apply(inputs, premises):
    spans = inputs.get('source_spans', [])
    answers = inputs.get('semantic_answers', [])
    seen = set()
    for answer in answers:
        if isinstance(answer, dict) and isinstance(answer.get('id'), str):
            seen.add(answer.get('id'))
    queries = []
    all_ids = []
    for span in spans:
        if isinstance(span, dict) and type(span.get('id')) is int and isinstance(span.get('text'), str):
            all_ids.append(span.get('id'))
    i = 0
    while i < len(spans):
        span = spans[i]
        if not isinstance(span, dict) or type(span.get('id')) is not int or not isinstance(span.get('text'), str):
            i += 1
            continue
        start = max(0, i - 2)
        window = []
        parts = []
        j = start
        while j <= i:
            prior = spans[j]
            if isinstance(prior, dict) and type(prior.get('id')) is int and isinstance(prior.get('text'), str):
                window.append(prior.get('id'))
                parts.append(prior.get('text'))
            j += 1
        low = ' '.join(parts).lower()
        current = span.get('text').lower()
        people = any(token in low for token in ('employee', 'director', 'officer', 'contractor', 'consultant', 'agent', 'representative', 'professional adviser', 'professional advisor', 'affiliate', 'controlled', 'third party', 'third-party', 'other person'))
        disclosure = people and any(token in low for token in ('disclos', 'restrict access', 'restrict disclosure', 'make accessible', 'provide access', 'divulge'))
        if disclosure:
            for operation in ('disclosure_modality', 'disclosure_recipient_scope', 'disclosure_conditions'):
                identity = operation + '|unit|' + str(span.get('id'))
                if identity not in seen:
                    queries.append({'id': identity, 'operation': operation, 'unit_ids': list(window)})
        protected = any(token in low for token in ('confidential information', 'document', 'material', 'copies', 'copy', 'record'))
        disposal = protected and any(token in low for token in ('return', 'destroy', 'delete'))
        retention = any(token in current for token in ('retain', 'retention', 'archiv', 'keep a copy'))
        if disposal:
            for operation in ('disposal_action', 'disposal_material_scope', 'disposal_trigger', 'retention_effect'):
                identity = operation + '|unit|' + str(span.get('id'))
                if identity not in seen:
                    queries.append({'id': identity, 'operation': operation, 'unit_ids': list(window)})
        elif retention:
            identity = 'retention_effect|unit|' + str(span.get('id'))
            if identity not in seen:
                queries.append({'id': identity, 'operation': 'retention_effect', 'unit_ids': list(window)})
        i += 1
    if all_ids:
        anchor = ','.join(str(value) for value in all_ids)
        for operation in ('scan_disclosure_permission', 'scan_disposal_obligation', 'scan_retention_effect'):
            identity = operation + '|all|' + anchor
            if identity not in seen:
                queries.append({'id': identity, 'operation': operation, 'unit_ids': list(all_ids)})
    return {'queries': queries}

value.source_concept_program:
def answer_units(answer):
    out = []
    values = answer.get('selected_evidence_unit_ids', answer.get('evidence_unit_ids', []))
    if isinstance(values, list):
        for value in values:
            if type(value) is int and value not in out:
                out.append(value)
    evidence = answer.get('evidence', [])
    if isinstance(evidence, list):
        for item in evidence:
            if isinstance(item, dict) and type(item.get('unit_id')) is int and item.get('unit_id') not in out:
                out.append(item.get('unit_id'))
    return out

def answer_anchor(answer):
    identity = answer.get('id', '')
    if not isinstance(identity, str) or '|unit|' not in identity:
        return ''
    return identity.rsplit('|unit|', 1)[1]

def source_words(ids, spans):
    parts = []
    for span in spans:
        if isinstance(span, dict) and span.get('id') in ids and isinstance(span.get('text'), str):
            parts.append(span.get('text'))
    return ' '.join(parts)

def participant_union(items):
    if not items:
        return None
    value = items[0]
    i = 1
    while i < len(items):
        value = ['participant_union', value, items[i]]
        i += 1
    return value

def recipient_term(choice):
    receiver = ['receiving_party']
    if choice == 'recipient_own_employees_officers_directors':
        return participant_union([['employees_of', receiver], ['officers_of', receiver], ['directors_of', receiver]])
    if choice == 'recipient_own_employees_directors_contractors':
        return participant_union([['employees_of', receiver], ['directors_of', receiver], ['independent_contractors_of', receiver]])
    if choice == 'recipient_own_employees_and_consultants':
        return participant_union([['employees_of', receiver], ['consultants_of', receiver]])
    if choice == 'recipient_affiliate_officers_directors_employees':
        owner = ['affiliates_of', receiver]
        return participant_union([['employees_of', owner], ['officers_of', owner], ['directors_of', owner]])
    if choice == 'recipient_own_and_controlled_personnel':
        related = ['controlled_entities_of', receiver]
        own = participant_union([['employees_of', receiver], ['officers_of', receiver], ['directors_of', receiver], ['representatives_of', receiver], ['agents_of', receiver]])
        controlled = participant_union([['employees_of', related], ['officers_of', related], ['directors_of', related], ['representatives_of', related], ['agents_of', related]])
        return ['participant_union', own, controlled]
    if choice == 'unrestricted_third_parties':
        return ['third_parties']
    return None

def material_term(choice):
    info = ['confidential_information']
    copies = ['copies_of', info]
    if choice == 'confidential_information_only':
        return info
    if choice in ('confidential_information_and_copies', 'stated_materials_and_copies'):
        return ['information_bundle', info, copies]
    if choice == 'information_copies_and_derivatives':
        return ['information_bundle', ['information_bundle', info, copies], ['derivative_materials_of', info]]
    return None

def trigger_term(choice):
    request = ['request_by', ['disclosing_party']]
    if choice == 'agreement_termination_or_counterparty_request':
        return ['trigger_alternative', ['agreement_termination'], request]
    if choice == 'purpose_completion_or_counterparty_request':
        return ['trigger_alternative', ['purpose_completion'], request]
    if choice == 'relationship_nonformation_deadline_or_counterparty_request':
        return ['trigger_alternative', ['relationship_nonformation_deadline'], request]
    if choice == 'counterparty_request_only':
        return request
    if choice == 'agreement_termination_only':
        return ['agreement_termination']
    return None

def add_fragment(rows, term, supports, queries):
    if term is None or not supports or not queries:
        return
    row = {'term': term, 'support_ids': sorted(set(supports)), 'query_ids': list(queries)}
    key = repr(row)
    for old in rows:
        if repr(old) == key:
            return
    rows.append(row)

def add_program_read(queries, answers, identity, operation, unit, choice):
    queries.append({'id': identity, 'operation': operation, 'unit_ids': [unit]})
    answers.append({'id': identity, 'choice': choice, 'evidence_unit_ids': [unit]})

def apply(inputs, premises):
    spans = inputs.get('source_spans', [])
    semantic = inputs.get('semantic_answers', [])
    groups = {}
    for answer in semantic:
        if not isinstance(answer, dict) or answer.get('choice') in (None, 'unknown'):
            continue
        anchor = answer_anchor(answer)
        operation = answer.get('operation')
        if anchor and isinstance(operation, str):
            groups.setdefault(anchor, {})[operation] = answer
    fragments = []
    unresolved = []
    program_queries = []
    program_answers = []
    text_by_id = {}
    for span in spans:
        if isinstance(span, dict) and type(span.get('id')) is int and isinstance(span.get('text'), str):
            text_by_id[span.get('id')] = span.get('text')
    for anchor, group in groups.items():
        try:
            focus = int(anchor)
        except ValueError:
            focus = -1
        current = text_by_id.get(focus, '')
        current_low = current.lower()
        local_disclosure = any(token in current_low for token in ('disclos', 'divulge', 'restrict access', 'restrict disclosure', 'make accessible', 'provide access'))
        false_attachment = ('signed the mandatory non-disclosure agreement' in current_low or 'hosted or taken outside' in current_low or 'send ' in current_low and 'outside' in current_low)
        modality = group.get('disclosure_modality')
        recipient = group.get('disclosure_recipient_scope')
        condition = group.get('disclosure_conditions')
        if modality is not None and recipient is not None and local_disclosure and not false_attachment:
            shared = sorted(set(answer_units(modality)).intersection(set(answer_units(recipient))))
            receiver = recipient_term(recipient.get('choice'))
            mode = modality.get('choice')
            if receiver is not None and mode in ('operative_class_permission', 'operative_general_prohibition', 'prohibition_with_embedded_class_permission') and shared:
                add_fragment(fragments, ['disclose', ['confidential_information'], receiver], shared, [modality.get('id'), recipient.get('id')])
            elif mode != 'not_an_operative_disclosure_rule':
                unresolved.append('unrepresented disclosure recipient at current unit ' + anchor)
        if condition is not None:
            supports = answer_units(condition)
            wording = source_words(supports, spans)
            if condition.get('choice') == 'need_to_know_and_confidentiality_bound' and supports:
                add_fragment(fragments, ['and_condition', ['need_to_know', wording], ['confidentiality_bound', wording]], supports, [condition.get('id')])
            elif condition.get('choice') == 'no_additional_condition' and supports:
                add_fragment(fragments, ['no_condition'], supports, [condition.get('id')])
        action_answer = group.get('disposal_action')
        material_answer = group.get('disposal_material_scope')
        if action_answer is not None and material_answer is not None:
            shared = sorted(set(answer_units(action_answer)).intersection(set(answer_units(material_answer))))
            material = material_term(material_answer.get('choice'))
            wording = source_words(shared, spans)
            choice = action_answer.get('choice')
            action = None
            if material is not None and choice == 'return_only':
                action = ['return_to', material, ['disclosing_party']]
            elif material is not None and choice == 'destroy_only':
                action = ['destroy', material]
            elif material is not None and choice == 'return_or_destroy_unallocated':
                action = ['action_alternative', ['return_to', material, ['disclosing_party']], ['destroy', material]]
            elif material is not None and choice == 'return_or_destroy_at_counterparty_option':
                action = ['source_action_alternative', ['return_to', material, ['disclosing_party']], ['destroy', material], wording]
            elif material is not None and choice == 'return_or_destroy_with_authorization_on_destroy':
                action = ['source_authorized_action_alternative', ['return_to', material, ['disclosing_party']], ['destroy', material], wording]
            if action is not None and shared:
                add_fragment(fragments, action, shared, [action_answer.get('id'), material_answer.get('id')])
        trigger_answer = group.get('disposal_trigger')
        if trigger_answer is not None:
            supports = answer_units(trigger_answer)
            trigger = trigger_term(trigger_answer.get('choice'))
            if trigger is not None and supports:
                add_fragment(fragments, trigger, supports, [trigger_answer.get('id')])
        retention = group.get('retention_effect')
        if retention is not None:
            supports = answer_units(retention)
            wording = source_words(supports, spans)
            choice = retention.get('choice')
            if choice == 'no_explicit_exception_in_complete_disposal_clause' and supports:
                add_fragment(fragments, ['no_exceptions'], supports, [retention.get('id')])
            elif choice in ('archival_copy_permission', 'qualified_retention_permission') and supports:
                info = ['copies_of', ['confidential_information']] if choice == 'archival_copy_permission' else ['confidential_information']
                condition_term = ['retention_condition', wording]
                add_fragment(fragments, ['exception_set', ['retention_exception', ['receiving_party'], info, condition_term]], supports, [retention.get('id')])
                add_fragment(fragments, info, supports, [retention.get('id')])
                add_fragment(fragments, condition_term, supports, [retention.get('id')])
                add_fragment(fragments, ['after_disposal'], supports, [retention.get('id')])
            elif choice == 'explicit_post_disposal_retention_prohibition' and supports:
                add_fragment(fragments, ['confidential_information'], supports, [retention.get('id')])
                add_fragment(fragments, ['after_disposal'], supports, [retention.get('id')])
    for span in spans:
        if not isinstance(span, dict) or type(span.get('id')) is not int or not isinstance(span.get('text'), str):
            continue
        unit = span.get('id')
        wording = span.get('text')
        low = wording.lower()
        base = 'program:' + str(unit) + ':'
        if ('confidential information' in low and ('shall mean' in low or 'means all' in low or 'includes all' in low)):
            identity = base + 'definition'
            add_program_read(program_queries, program_answers, identity, 'source_clause_kind', unit, 'source_definition')
        permission_agents = 'restrict access to the confidential information' in low and 'agents and professional advisers' in low and 'disclosure is necessary' in low
        permission_consultants = 'restrict disclosure' in low and 'employees' in low and 'consultants' in low and 'need to know' in low
        if permission_agents or permission_consultants:
            kind_id = base + 'clause'
            add_program_read(program_queries, program_answers, kind_id, 'source_clause_kind', unit, 'source_permission')
            atoms = []
            atom_queries = []
            if permission_agents:
                agent_id = base + 'recipient-agent'
                adviser_id = base + 'recipient-professional-adviser'
                add_program_read(program_queries, program_answers, agent_id, 'source_recipient_atom', unit, 'recipient_atom_agent')
                add_program_read(program_queries, program_answers, adviser_id, 'source_recipient_atom', unit, 'recipient_atom_professional_adviser')
                atoms = [['agents_of', ['receiving_party']], ['professional_advisors_of', ['receiving_party']]]
                atom_queries = [agent_id, adviser_id]
                condition_choice = 'condition_extent_necessary_for_purpose'
                condition_term = ['extent_necessary', wording]
            else:
                employee_id = base + 'recipient-employee'
                consultant_id = base + 'recipient-consultant'
                add_program_read(program_queries, program_answers, employee_id, 'source_recipient_atom', unit, 'recipient_atom_employee')
                add_program_read(program_queries, program_answers, consultant_id, 'source_recipient_atom', unit, 'recipient_atom_consultant')
                atoms = [['employees_of', ['receiving_party']], ['consultants_of', ['receiving_party']]]
                atom_queries = [employee_id, consultant_id]
                condition_choice = 'condition_need_to_know'
                condition_term = ['need_to_know', wording]
            condition_id = base + 'condition'
            add_program_read(program_queries, program_answers, condition_id, 'source_condition_kind', unit, condition_choice)
            add_fragment(fragments, ['disclose', ['confidential_information'], participant_union(atoms)], [unit], [kind_id] + atom_queries)
            add_fragment(fragments, condition_term, [unit], [condition_id])
        written_consent_ban = ('without prior written consent' in low and ('divulge' in low or 'disclos' in low) and ('third parties' in low or 'third party' in low))
        service_ban = ('not misuse' in low and 'disclos' in low and 'any other person' in low and 'except as is required in the course of service' in low)
        cross_reference_ban = ('except as provided herein' in low and 'prohibited from disclosing' in low and 'third parties' in low)
        if written_consent_ban or service_ban or cross_reference_ban:
            kind_id = base + 'clause'
            recipient_id = base + 'recipient-third-party'
            condition_id = base + 'condition'
            exception_id = base + 'exception'
            add_program_read(program_queries, program_answers, kind_id, 'source_clause_kind', unit, 'source_prohibition')
            add_program_read(program_queries, program_answers, recipient_id, 'source_recipient_atom', unit, 'recipient_atom_third_party')
            add_program_read(program_queries, program_answers, condition_id, 'source_condition_kind', unit, 'condition_no_additional')
            if written_consent_ban:
                exception_choice = 'exception_written_consent'
                exception_term = ['authorization_exception', wording]
            elif service_ban:
                exception_choice = 'exception_required_service'
                exception_term = ['purpose_exception', wording]
            else:
                exception_choice = 'exception_cross_reference'
                exception_term = ['cross_reference_exception', wording]
            add_program_read(program_queries, program_answers, exception_id, 'source_exception_kind', unit, exception_choice)
            add_fragment(fragments, ['disclose', ['confidential_information'], ['third_parties']], [unit], [kind_id, recipient_id])
            add_fragment(fragments, ['no_condition'], [unit], [condition_id])
            add_fragment(fragments, ['exception_set', exception_term], [unit], [exception_id])
    return {'queries': program_queries, 'answers': program_answers, 'fragments': fragments, 'unresolved': unresolved}
